describe("the 2v2 turn under Neutralizing Gas against pinned Showdown (verifier cases)", () => {
  for (const c of CASES) {
    it(`${c.id}: ${c.title}`, async () => {
      const result = calculateDoublesTurn(await input(c));
      expect(result.status, c.checks).toBe("ready");
      if (result.status !== "ready") return;
      // Exhaustive cases are exact to 1e-9; a sampled one (exact: false) to 0.015 in its chances and 0.5 HP in its average.
      const digits = c.exact ? 9 : 1;
      for (const slot of SLOTS) {
        const want = c.hp[slot], got = result.hp[slot];
        if (!want) { expect(got, slot).toBeNull(); continue; }
        expect(got, slot).not.toBeNull();
        expect({ start: got!.start, maximum: got!.maximum, low: got!.low, high: got!.high }, `${c.id} ${slot}`).toEqual({ start: want.start, maximum: want.maximum, low: want.low, high: want.high });
        if (c.exact) expect({ min: got!.min, max: got!.max }, `${c.id} ${slot}`).toEqual({ min: want.min, max: want.max });
        else expect(got!.min <= want.min && got!.max >= want.max, `${c.id} ${slot} range`).toBe(true);
        expect(got!.average, `${c.id} ${slot} average`).toBeCloseTo(want.average, c.exact ? 9 : 0);
        expect(Math.abs(got!.koChance - want.koChance), `${c.id} ${slot} KO chance`).toBeLessThanOrEqual(c.exact ? 1e-9 : 0.015);
        expect(got!.faintsBeforeMoving ?? 0, `${c.id} ${slot} faints before moving`).toBeCloseTo(want.faintsBeforeMoving ?? 0, digits);
      }
      expect(result.steps.map((step) => step.slot).sort()).toEqual(Object.keys(c.steps).sort());
      for (const step of result.steps) {
        const want = c.steps[step.slot as DoublesSlotId]!;
        expect(step.moveId).toBe(want.moveId);
        expect(step.moves, `${c.id} ${step.slot} moves`).toBeCloseTo(want.moves, digits);
        const order = new Map(step.order.map((entry) => [entry.position, entry.chance]));
        for (const [position, chance] of want.order) expect(order.get(position) ?? 0, `${c.id} ${step.slot} order ${position}`).toBeCloseTo(chance, digits);
        expect([...order.keys()].every((position) => want.order.some(([p]) => p === position))).toBe(true);
        if (!want.hits.length) continue;
        for (const hit of want.hits) {
          const got = step.hits.find((h) => h.slot === hit.slot);
          expect(got, `${c.id} ${step.slot} → ${hit.slot}`).toBeDefined();
          expect(got!.reached, `${c.id} ${step.slot} → ${hit.slot} reached`).toBeCloseTo(hit.reached, digits);
          expect(got!.koChance, `${c.id} ${step.slot} → ${hit.slot} KO chance`).toBeCloseTo(hit.koChance, digits);
          if (hit.kind) expect(got!.kind === hit.kind || (hit.kind === "blocked" && got!.kind === "no-damage"), `${c.id} ${step.slot} → ${hit.slot} ${got!.kind}`).toBe(true);
          if (hit.min !== undefined) expect({ kind: got!.kind, min: got!.min, max: got!.max }, `${c.id} ${step.slot} → ${hit.slot}`).toEqual({ kind: "calculated", min: hit.min, max: hit.max });
        }
      }
    });
  }
});

const asCase = (g: (typeof GUARDED)[number]): Case => ({ ...g, checks: "", exact: true, hp: {} as Case["hp"], steps: {} });
const caseOf = (caseId: string): Case => CASES.find((c) => c.id === caseId) ?? asCase(GUARDED.find((g) => g.id === caseId)!);

describe("Neutralizing Gas in the 2v2 turn: guards and start rows (verifier cases)", () => {
  it("is not estimated where the gas ends or what it suppresses changes, with the reason", async () => {
    for (const g of GUARDED) {
      const result = calculateDoublesTurn(await input(asCase(g)));
      expect(result.status, g.id).toBe("not-estimated");
      if (result.status === "not-estimated") expect(result.reason, g.id).toBe(g.reason);
    }
  });

  it("lists each move's damage at the start of the turn as Showdown deals it, the gas on from the start", async () => {
    for (const caseId of new Set(START_ROWS.map(([id]) => id))) {
      const result = calculateDoublesTurn(await input(caseOf(caseId)));
      if (result.status === "issues") throw new Error(caseId);
      for (const [, slot, target, moveId, min, max] of START_ROWS.filter(([id]) => id === caseId)) {
        const row = result.startRows.find((entry) => entry.slot === slot && entry.target === target)?.row;
        expect(row && { moveId: row.moveId, kind: row.kind, min: row.min, max: row.max }, `${caseId} ${slot} -> ${target}`).toEqual({ moveId, kind: "calculated", min, max });
      }
    }
  });

  it("keeps the gas when a second holder is left, and needs no guard when nothing it suppressed is left", async () => {
    // VG18: Earthquake knocks out one holder; the other keeps Garchomp's Rough Skin off for Snorlax's Body Slam.
    const two = calculateDoublesTurn(await input(caseOf("VG18")));
    expect(two.status).toBe("ready");
    if (two.status === "ready") expect(two.facts).toContain("Neutralizing Gas suppresses the abilities of Garchomp and Snorlax.");
    // VG19: the holder is knocked out with a move to come, and Disguise, Gulp Missile and Zero to Hero cannot be suppressed.
    const none = calculateDoublesTurn(await input(caseOf("VG19")));
    expect(none.status).toBe("ready");
    if (none.status === "ready") expect(none.facts.some((fact) => fact.startsWith("Neutralizing Gas"))).toBe(false);
    // VG61: a holder fainted before the turn (0 HP, no replacement) suppresses nothing: Thick Fat halves Flamethrower.
    const fainted = calculateDoublesTurn(await input(caseOf("VG61")));
    expect(fainted.status).toBe("ready");
    if (fainted.status === "ready") expect(fainted.facts.some((fact) => fact.startsWith("Neutralizing Gas"))).toBe(false);
  });
});
